import React, { useMemo, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { getToken, getUser, logout } from "../utils/auth";
import { motion, AnimatePresence } from "framer-motion";
import { Menu, X, ShieldCheck } from "lucide-react";

export default function Navbar() {
  const nav = useNavigate();
  const loc = useLocation();

  const token = getToken();
  const user = getUser();

  const [open, setOpen] = useState(false);

  const links = useMemo(() => {
    const base = [
      { to: "/report", label: "Scam Check" },
      { to: "/pricing", label: "Pricing" }
    ];

    // Optional future route
    // base.push({ to: "/emergency", label: "Emergency" });

    if (token && user?.role === "USER") {
      base.push({ to: "/portal", label: "My Portal" });
    }

    return base;
  }, [token, user]);

  function isActive(path) {
    return loc.pathname === path;
  }

  function handleLogout() {
    logout();
    nav("/");
  }

  return (
    <div className="sticky top-0 z-50">
      {/* Glass bar */}
      <div className="border-b bg-white/80 backdrop-blur-xl">
        <div className="max-w-6xl mx-auto px-4 py-4 flex items-center justify-between gap-4">
          {/* Logo */}
          <Link
            to="/"
            className="flex items-center gap-3 group select-none"
          >
            <motion.div
              initial={{ scale: 0.9, rotate: -6, opacity: 0 }}
              animate={{ scale: 1, rotate: 0, opacity: 1 }}
              transition={{ duration: 0.35 }}
              className="w-11 h-11 rounded-2xl bg-gray-900 text-white flex items-center justify-center shadow"
            >
              <ShieldCheck size={22} />
            </motion.div>

            <div>
              <div className="font-extrabold text-xl tracking-tight leading-none group-hover:opacity-90">
                CyberRaksha
              </div>
              <div className="text-xs font-medium text-gray-500">
                Scam se Suraksha. Digital Raksha.
              </div>
            </div>
          </Link>

          {/* Desktop links */}
          <div className="hidden md:flex items-center gap-2">
            {links.map((l) => (
              <Link
                key={l.to}
                to={l.to}
                className={`px-4 py-2 rounded-2xl text-sm font-semibold transition ${
                  isActive(l.to)
                    ? "bg-gray-900 text-white"
                    : "text-gray-700 hover:bg-gray-100"
                }`}
              >
                {l.label}
              </Link>
            ))}

            {/* Auth */}
            {token ? (
              <button
                onClick={handleLogout}
                className="ml-2 px-4 py-2 rounded-2xl bg-gray-900 text-white text-sm font-semibold hover:opacity-90 transition"
              >
                Logout
              </button>
            ) : (
              <div className="flex gap-2 ml-2">
                <Link
                  to="/login"
                  className="px-4 py-2 rounded-2xl border text-sm font-semibold hover:bg-gray-50 transition"
                >
                  User Login
                </Link>

                <Link
                  to="/admin/login"
                  className="px-4 py-2 rounded-2xl bg-gray-900 text-white text-sm font-semibold hover:opacity-90 transition"
                >
                  Admin
                </Link>
              </div>
            )}
          </div>

          {/* Mobile menu button */}
          <button
            className="md:hidden p-3 rounded-2xl border bg-white hover:bg-gray-50 transition"
            onClick={() => setOpen((p) => !p)}
            aria-label="Menu"
          >
            {open ? <X size={18} /> : <Menu size={18} />}
          </button>
        </div>

        {/* Mobile dropdown */}
        <AnimatePresence>
          {open && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: "auto", opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              transition={{ duration: 0.25 }}
              className="md:hidden overflow-hidden"
            >
              <div className="max-w-6xl mx-auto px-4 pb-4">
                <div className="bg-white rounded-3xl border shadow-sm p-3 space-y-2">
                  {links.map((l) => (
                    <Link
                      key={l.to}
                      to={l.to}
                      onClick={() => setOpen(false)}
                      className={`block px-4 py-3 rounded-2xl text-sm font-semibold transition ${
                        isActive(l.to)
                          ? "bg-gray-900 text-white"
                          : "text-gray-700 hover:bg-gray-50"
                      }`}
                    >
                      {l.label}
                    </Link>
                  ))}

                  {token ? (
                    <button
                      onClick={() => {
                        setOpen(false);
                        handleLogout();
                      }}
                      className="w-full px-4 py-3 rounded-2xl bg-gray-900 text-white text-sm font-semibold hover:opacity-90 transition"
                    >
                      Logout
                    </button>
                  ) : (
                    <div className="grid grid-cols-2 gap-2">
                      <Link
                        to="/login"
                        onClick={() => setOpen(false)}
                        className="px-4 py-3 rounded-2xl border text-sm font-semibold hover:bg-gray-50 transition text-center"
                      >
                        User Login
                      </Link>

                      <Link
                        to="/admin/login"
                        onClick={() => setOpen(false)}
                        className="px-4 py-3 rounded-2xl bg-gray-900 text-white text-sm font-semibold hover:opacity-90 transition text-center"
                      >
                        Admin
                      </Link>
                    </div>
                  )}
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}
